/// Generates the spec index of the board AI (specs/16 §10.1): the tables of
/// `specs/README.md` and the headings (levels 1–3) of every spec file, as
/// Dart constants in
/// `wonky_server/lib/src/platform/board/ai/spec_index.g.dart`. Task prompts
/// include the suite part plus the part of the task's app, so the server
/// needs no checkout of the specs.
///
/// Usage (from the repository root, no `pub get` needed):
///
/// ```sh
/// dart run tool/spec_index.dart          # (re)write the generated file
/// dart run tool/spec_index.dart --check  # exit 1 when it is out of date
/// ```
library;

import 'dart:io';

const _output = 'wonky_server/lib/src/platform/board/ai/spec_index.g.dart';
const _apps = ['drive', 'write', 'sheets', 'slides'];

void main(List<String> args) {
  final check = args.contains('--check');
  if (args.any((a) => a != '--check')) {
    stderr.writeln('Usage: dart run tool/spec_index.dart [--check]');
    exit(64);
  }
  final root = _repoRoot();
  final generated = _formatted(generate(root));
  final file = File('${root.path}/$_output');
  if (check) {
    final current = file.existsSync() ? file.readAsStringSync() : '';
    if (current != generated) {
      stderr.writeln(
        '$_output is out of date: run `dart run tool/spec_index.dart`.',
      );
      exit(1);
    }
    stdout.writeln('$_output is up to date.');
    return;
  }
  file.writeAsStringSync(generated);
  stdout.writeln('Wrote $_output (${generated.length} chars).');
}

/// [source] as `dart format` writes it (so formatting the package keeps
/// the file up to date).
String _formatted(String source) {
  final dir = Directory.systemTemp.createTempSync('spec_index');
  try {
    final f = File('${dir.path}/spec_index.g.dart')..writeAsStringSync(source);
    final r = Process.runSync(Platform.resolvedExecutable, ['format', f.path]);
    if (r.exitCode != 0) {
      stderr.writeln('dart format failed: ${r.stderr}');
      exit(1);
    }
    return f.readAsStringSync();
  } finally {
    dir.deleteSync(recursive: true);
  }
}

Directory _repoRoot() {
  var dir = File(Platform.script.toFilePath()).parent.parent;
  if (!Directory('${dir.path}/specs').existsSync()) dir = Directory.current;
  if (!Directory('${dir.path}/specs').existsSync()) {
    stderr.writeln('Run this from the repository root.');
    exit(64);
  }
  return dir;
}

/// The content of the generated file for the repository at [root].
String generate(Directory root) {
  final specs = '${root.path}/specs';
  final readme = _readmeTables(File('$specs/README.md').readAsStringSync());
  final suite = _headingsOf([
    for (final f in _mdFiles(Directory(specs)))
      if (!_posix(f.path).endsWith('/README.md')) f,
  ], root);
  final apps = {
    for (final app in _apps)
      if (Directory('$specs/wonky_$app').existsSync())
        app: _headingsOf(_mdFiles(Directory('$specs/wonky_$app')), root),
  };
  final b = StringBuffer()
    ..writeln('// GENERATED by tool/spec_index.dart. Do not edit by hand:')
    ..writeln('// run `dart run tool/spec_index.dart` after changing specs/.')
    ..writeln()
    ..writeln('// ignore_for_file: lines_longer_than_80_chars')
    ..writeln()
    ..writeln('/// The tables of `specs/README.md`.')
    ..writeln('const specIndexReadme =')
    ..write(_literal('## specs/README.md\n$readme'))
    ..writeln(';')
    ..writeln()
    ..writeln('/// Headings of the suite specs (`specs/*.md`).')
    ..writeln('const specIndexSuite =')
    ..write(_literal(suite))
    ..writeln(';')
    ..writeln()
    ..writeln(
      '/// Headings of the app specs (`specs/wonky_<app>/*.md`) by app.',
    )
    ..writeln('const specIndexApps = <String, String>{');
  for (final e in apps.entries) {
    b
      ..writeln("  '${e.key}':")
      ..write(_literal(e.value, indent: '    '))
      ..writeln(',');
  }
  b.writeln('};');
  return b.toString();
}

List<File> _mdFiles(Directory dir) =>
    dir
        .listSync()
        .whereType<File>()
        .where((f) => f.path.endsWith('.md'))
        .toList()
      ..sort((a, b) => a.path.compareTo(b.path));

/// The table rows (separator rows dropped) and level-2 headings of the
/// README.
String _readmeTables(String text) {
  final out = <String>[];
  for (final line in _outsideFences(text)) {
    if (line.startsWith('## ')) {
      out.add(line);
    } else if (line.startsWith('|') &&
        !RegExp(r'^\|[\s\-:|]+\|$').hasMatch(line.trim())) {
      out.add(_unlink(line, prefix: 'specs/'));
    }
  }
  return out.join('\n');
}

/// `path` lines followed by the indented headings (levels 1–3) of [files].
String _headingsOf(List<File> files, Directory root) {
  final out = <String>[];
  for (final f in files) {
    final rel = _posix(f.path.substring(root.path.length + 1));
    out.add(rel);
    for (final line in _outsideFences(f.readAsStringSync())) {
      final m = RegExp(r'^(#{1,3}) +(.+?)\s*$').firstMatch(line);
      if (m == null) continue;
      final level = m[1]!.length;
      out.add('${'  ' * level}${'#' * level} ${_unlink(m[2]!)}');
    }
  }
  return out.join('\n');
}

/// The lines of [text] outside fenced code blocks.
Iterable<String> _outsideFences(String text) sync* {
  var fenced = false;
  for (final line in text.replaceAll('\r\n', '\n').split('\n')) {
    if (line.trimLeft().startsWith('```')) {
      fenced = !fenced;
      continue;
    }
    if (!fenced) yield line;
  }
}

/// Markdown links reduced to their text plus target (`text (target)`);
/// relative targets get [prefix].
String _unlink(String s, {String prefix = ''}) =>
    s.replaceAllMapped(RegExp(r'\[([^\]]+)\]\(([^)]+)\)'), (m) {
      final target = m[2]!.contains(':') ? m[2]! : '$prefix${m[2]}';
      return '${m[1]} ($target)';
    });

/// [s] as adjacent single-quoted Dart string literals, one per line.
String _literal(String s, {String indent = '    '}) {
  final lines = s.split('\n');
  final b = StringBuffer();
  for (var i = 0; i < lines.length; i++) {
    final escaped = lines[i]
        .replaceAll(r'\', r'\\')
        .replaceAll("'", r"\'")
        .replaceAll(r'$', r'\$');
    final nl = i < lines.length - 1 ? r'\n' : '';
    b.write("$indent'$escaped$nl'");
    if (i < lines.length - 1) b.writeln();
  }
  return b.toString();
}

/// [path] with `/` separators (Windows lists `specs\x.md`).
String _posix(String path) => path.replaceAll(r'\', '/');
